AND ${col}erp_tenant_id IN (
    SELECT st.id FROM sys_tenant st
    WHERE st.deleted = 0 AND st.parent_wms_tenant_id IN
    #{e}
)

mapper.select:
SELECT COALESCE(SUM(p.quantity), 0) AS onHandQty, COUNT(DISTINCT p.sku_code) AS skuCount, COUNT(DISTINCT p.erp_tenant_id) AS ownerCount FROM wms_physical_inventory p INNER JOIN wms_warehouse w ON w.id = p.warehouse_id
w.warehouse_type = 'OWN' AND w.deleted = 0 AND p.quantity > 0
AND p.warehouse_id IN #{w}

SELECT COALESCE(SUM(i.actual_quantity), 0) AS qty, COUNT(DISTINCT o.id) AS orders FROM wms_purchase_inbound_order o LEFT JOIN wms_purchase_inbound_order_item i ON i.inbound_order_id = o.id
o.deleted = 0 AND o.order_status IN ('RECEIVED', 'COMPLETED') AND o.receive_time IS NOT NULL AND DATE(CONVERT_TZ(o.receive_time, '+08:00', '+03:00')) = #{qo.todayDate}
AND o.warehouse_id IN #{w}

SELECT COALESCE(SUM(total_quantity), 0) AS qty, COUNT(*) AS orders FROM wms_sales_outbound_order
order_status IN ('SHIPPED', 'COMPLETED') AND shipped_time IS NOT NULL AND DATE(CONVERT_TZ(shipped_time, '+08:00', '+03:00')) = #{qo.todayDate}
AND warehouse_id IN #{w}

SELECT COUNT(*) FROM wms_purchase_inbound_order
deleted = 0 AND order_status = 'SUBMITTED'
AND warehouse_id IN #{w}

SELECT COUNT(*) FROM wms_purchase_inbound_order
deleted = 0 AND order_status = 'RECEIVED'
AND warehouse_id IN #{w}

SELECT COUNT(*) FROM wms_sales_outbound_order
order_status IN ('CONFIRMED', 'PICKING', 'PICKED')
AND warehouse_id IN #{w}

SELECT COUNT(*) FROM wms_sales_outbound_order
order_status = 'PACKED'
AND warehouse_id IN #{w}

SELECT w.id AS warehouseId, w.warehouse_name AS warehouseName, (SELECT COUNT(*) FROM wms_location l WHERE l.warehouse_id = w.id AND l.deleted = 0 AND l.is_virtual = 0) AS total, (SELECT COUNT(DISTINCT p.location_code) FROM wms_physical_inventory p JOIN wms_location l ON l.warehouse_id = p.warehouse_id AND l.location_code = p.location_code AND l.deleted = 0 AND l.is_virtual = 0 WHERE p.warehouse_id = w.id AND p.quantity > 0
) AS used FROM wms_warehouse w
w.deleted = 0 AND w.warehouse_type = 'OWN'
AND w.id IN #{wid}
ORDER BY w.id

SELECT zt.zone_type AS zone, COALESCE(loc.cnt, 0) AS locationCount, COALESCE(inv.qty, 0) AS invQty FROM ( SELECT DISTINCT zone_type FROM wms_zone
deleted = 0
AND warehouse_id IN #{w}
) zt LEFT JOIN ( SELECT z.zone_type AS zone_type, COUNT(l.id) AS cnt FROM wms_location l JOIN wms_zone z ON z.id = l.zone_id AND z.deleted = 0
l.deleted = 0 AND l.is_virtual = 0
AND l.warehouse_id IN #{w}
GROUP BY z.zone_type ) loc ON loc.zone_type = zt.zone_type LEFT JOIN ( SELECT z.zone_type AS zone_type, COALESCE(SUM(p.quantity), 0) AS qty FROM wms_physical_inventory p JOIN wms_zone z ON z.id = p.zone_id AND z.deleted = 0
AND p.warehouse_id IN #{w}
GROUP BY z.zone_type ) inv ON inv.zone_type = zt.zone_type

SELECT DATE_FORMAT(CONVERT_TZ(receive_time, '+08:00', '+03:00'), '%Y-%m-%d') AS bizDate, COUNT(*) AS cnt FROM wms_purchase_inbound_order
deleted = 0 AND order_status IN ('RECEIVED', 'COMPLETED') AND receive_time IS NOT NULL AND DATE(CONVERT_TZ(receive_time, '+08:00', '+03:00')) BETWEEN #{qo.startDate} AND #{qo.endDate}
AND warehouse_id IN #{w}
GROUP BY DATE_FORMAT(CONVERT_TZ(receive_time, '+08:00', '+03:00'), '%Y-%m-%d')

SELECT DATE_FORMAT(CONVERT_TZ(shipped_time, '+08:00', '+03:00'), '%Y-%m-%d') AS bizDate, COUNT(*) AS cnt FROM wms_sales_outbound_order
order_status IN ('SHIPPED', 'COMPLETED') AND shipped_time IS NOT NULL AND DATE(CONVERT_TZ(shipped_time, '+08:00', '+03:00')) BETWEEN #{qo.startDate} AND #{qo.endDate}
AND warehouse_id IN #{w}
GROUP BY DATE_FORMAT(CONVERT_TZ(shipped_time, '+08:00', '+03:00'), '%Y-%m-%d')

SELECT DATE_FORMAT(return_date, '%Y-%m-%d') AS bizDate, COUNT(*) AS cnt FROM wms_return_inbound_order
deleted = 0 AND return_status = 'COMPLETED' AND return_date BETWEEN #{qo.startDate} AND #{qo.endDate}
AND warehouse_id IN #{w}
GROUP BY return_date

SELECT op.id AS wmsTenantId, op.tenant_name AS operatorName, COALESCE(SUM(p.quantity), 0) AS qty FROM wms_physical_inventory p JOIN wms_warehouse w ON w.id = p.warehouse_id AND w.warehouse_type = 'OWN' AND w.deleted = 0 JOIN sys_tenant owner ON owner.id = p.erp_tenant_id AND owner.deleted = 0 JOIN sys_tenant op ON op.id = owner.parent_wms_tenant_id AND op.deleted = 0
p.quantity > 0
AND p.warehouse_id IN #{w}
AND op.id IN #{e}
GROUP BY op.id, op.tenant_name HAVING qty > 0 ORDER BY qty DESC LIMIT 10

SELECT op.id AS wmsTenantId, op.tenant_name AS operatorName, COUNT(*) AS qty FROM ( SELECT erp_tenant_id FROM wms_purchase_inbound_order
deleted = 0 AND order_status IN ('RECEIVED', 'COMPLETED') AND receive_time IS NOT NULL AND DATE(CONVERT_TZ(receive_time, '+08:00', '+03:00')) BETWEEN #{qo.startDate} AND #{qo.endDate}
AND warehouse_id IN #{w}
UNION ALL SELECT erp_tenant_id FROM wms_sales_outbound_order
order_status IN ('SHIPPED', 'COMPLETED') AND shipped_time IS NOT NULL AND DATE(CONVERT_TZ(shipped_time, '+08:00', '+03:00')) BETWEEN #{qo.startDate} AND #{qo.endDate}
AND warehouse_id IN #{w}
) s JOIN sys_tenant owner ON owner.id = s.erp_tenant_id AND owner.deleted = 0 JOIN sys_tenant op ON op.id = owner.parent_wms_tenant_id AND op.deleted = 0 GROUP BY op.id, op.tenant_name ORDER BY qty DESC LIMIT 10
